algorithms.pseudocode:
Input: generators sigma, tau in S_n, word length m
Output: closedWordCount(sigma, tau, m)

dist <- {identity: 1}
for step in 1..m:
  new_dist <- empty map
  for (g, count) in dist:
    for gen in {sigma, sigma^-1, tau, tau^-1}:
      new_dist[gen * g] += count
  dist <- new_dist
return dist[identity]

Time: O(m * n!)   Space: O(n!)
